-- NOMINA2: instalación completa y autónoma para Oracle 21c XE.
-- Comparte únicamente este archivo; no necesita otros archivos SQL.
-- Conectar con un usuario de aplicación de un esquema VACÍO en XEPDB1.
-- Ejecutar en modo SCRIPT completo (SQLPlus/SQLcl o Ejecutar script en SQL Developer).
-- ADMIN de la aplicación: admin.inicial / Nomina2!Temporal2026 (cambio obligatorio).
WHENEVER OSERROR EXIT FAILURE
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF
SET SQLBLANKLINES ON
SET SERVEROUTPUT ON
DECLARE
  N NUMBER;
BEGIN
  SELECT COUNT(*) INTO N FROM USER_TABLES;
  IF USER IN ('SYS','SYSTEM') OR N<>0 THEN
    RAISE_APPLICATION_ERROR(-20093,'Conéctate con un usuario de aplicación cuyo esquema esté vacío y ejecuta el archivo completo.');
  END IF;
END;
/

-- ==================== 01_esquema.sql ====================
-- DDL real de Oracle 21c XE mediante DBMS_METADATA. Ejecutar en un esquema vacío.
-- Opcional: como SYS en XEPDB1, antes de conectar con el usuario de aplicación:
-- CREATE USER NOMINA2 IDENTIFIED BY "CAMBIA_ESTA_CLAVE";
-- GRANT CREATE SESSION, CREATE TABLE, CREATE SEQUENCE, CREATE PROCEDURE,
--       CREATE TRIGGER, CREATE VIEW, CREATE TYPE, CREATE SYNONYM TO NOMINA2;
-- GRANT UNLIMITED TABLESPACE TO NOMINA2;
WHENEVER OSERROR EXIT FAILURE
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF SQLBLANKLINES ON
ALTER SESSION SET TIME_ZONE='America/Guatemala';

-- TABLE: PARQUEO_TARIFAS
CREATE TABLE "PARQUEO_TARIFAS" 
   (	"ID_PARQUEO_TARIFA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"VEHICULO" VARCHAR2(5 CHAR) NOT NULL ENABLE, 
	"MONTO" NUMBER(12,2) NOT NULL ENABLE, 
	"VIGENTE_DESDE" DATE NOT NULL ENABLE, 
	"VIGENTE_HASTA" DATE, 
	"MOTIVO" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_PARQUEO_TARIFAS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_PARQUEO_TARIFAS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION>=FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_PARQUEO_TARIFA_1" CHECK (VEHICULO IN ('CARRO','MOTO') AND MONTO>0) ENABLE, 
	 CONSTRAINT "CK_PARQUEO_TARIFA_2" CHECK (VIGENTE_HASTA IS NULL OR VIGENTE_HASTA>=VIGENTE_DESDE) ENABLE, 
	 CONSTRAINT "PK_PARQUEO_TARIFAS" PRIMARY KEY ("ID_PARQUEO_TARIFA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_PARQUEO_TARIFA" UNIQUE ("VEHICULO", "VIGENTE_DESDE")
  USING INDEX  ENABLE
   );

-- TABLE: PRUEBA_INFRAESTRUCTURA
CREATE TABLE "PRUEBA_INFRAESTRUCTURA" 
   (	"ID_PRUEBA_INFRAESTRUCTURA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"DESCRIPCION" VARCHAR2(100) NOT NULL ENABLE, 
	"CREADO_POR" VARCHAR2(30) DEFAULT USER NOT NULL ENABLE, 
	"FECHA_CREACION" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	"MODIFICADO_POR" VARCHAR2(30), 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CHECK (ACTIVO IN (0, 1)) ENABLE, 
	 PRIMARY KEY ("ID_PRUEBA_INFRAESTRUCTURA")
  USING INDEX  ENABLE, 
	 UNIQUE ("DESCRIPCION")
  USING INDEX  ENABLE
   );

-- TABLE: VERSION_ESQUEMA
CREATE TABLE "VERSION_ESQUEMA" 
   (	"ID_VERSION_ESQUEMA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"VERSION" NUMBER(6,0) NOT NULL ENABLE, 
	"ARCHIVO" VARCHAR2(200) NOT NULL ENABLE, 
	"CHECKSUM" CHAR(64) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(10) NOT NULL ENABLE, 
	"FECHA_CREACION" TIMESTAMP (6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"FECHA_APLICACION" TIMESTAMP (6) WITH TIME ZONE, 
	 CHECK (ESTADO IN ('APLICANDO', 'APLICADA', 'FALLIDA')) ENABLE, 
	 PRIMARY KEY ("ID_VERSION_ESQUEMA")
  USING INDEX  ENABLE, 
	 UNIQUE ("VERSION")
  USING INDEX  ENABLE
   );

-- TABLE: ROLES
CREATE TABLE "ROLES" 
   (	"ID_ROL" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(40 CHAR) NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(120 CHAR) NOT NULL ENABLE, 
	"DESCRIPCION" VARCHAR2(500 CHAR), 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_ROLES_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_ROLES_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_ROLES_1" CHECK (CODIGO IN ('ADMIN','RH','EMPLEADO')) ENABLE, 
	 CONSTRAINT "PK_ROLES" PRIMARY KEY ("ID_ROL")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_ROLES_1" UNIQUE ("CODIGO")
  USING INDEX  ENABLE
   );

-- TABLE: USUARIOS
CREATE TABLE "USUARIOS" 
   (	"ID_USUARIO" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_ROL" NUMBER NOT NULL ENABLE, 
	"USUARIO" VARCHAR2(80 CHAR) NOT NULL ENABLE, 
	"CORREO" VARCHAR2(254 CHAR) NOT NULL ENABLE, 
	"CONTRASENA_HASH" VARCHAR2(255 CHAR) NOT NULL ENABLE, 
	"CAMBIO_OBLIGATORIO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"INTENTOS_FALLIDOS" NUMBER(2,0) DEFAULT 0 NOT NULL ENABLE, 
	"BLOQUEADO_HASTA" DATE, 
	"ULTIMO_ACCESO" DATE, 
	"CONTRASENA_CAMBIADA_EN" DATE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_USUARIOS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_USUARIOS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_USUARIOS_1" CHECK (REGEXP_LIKE(USUARIO, '^[a-z][a-z0-9.]{2,79}$', 'c')) ENABLE, 
	 CONSTRAINT "CK_USUARIOS_2" CHECK (CORREO = LOWER(TRIM(CORREO)) AND INSTR(CORREO, '@') > 1) ENABLE, 
	 CONSTRAINT "CK_USUARIOS_3" CHECK (CONTRASENA_HASH LIKE '$argon2id$%') ENABLE, 
	 CONSTRAINT "CK_USUARIOS_4" CHECK (CAMBIO_OBLIGATORIO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_USUARIOS_5" CHECK (INTENTOS_FALLIDOS BETWEEN 0 AND 99) ENABLE, 
	 CONSTRAINT "PK_USUARIOS" PRIMARY KEY ("ID_USUARIO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_USUARIOS_1" UNIQUE ("USUARIO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_USUARIOS_2" UNIQUE ("CORREO")
  USING INDEX  ENABLE
   );

-- TABLE: ANUNCIOS
CREATE TABLE "ANUNCIOS" 
   (	"ID_ANUNCIO" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"TITULO" VARCHAR2(200 CHAR) NOT NULL ENABLE, 
	"CONTENIDO" CLOB NOT NULL ENABLE, 
	"VIGENTE_DESDE" DATE NOT NULL ENABLE, 
	"VIGENTE_HASTA" DATE NOT NULL ENABLE, 
	"PARA_TODOS" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"VERSION" NUMBER(10,0) DEFAULT 1 NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(80 CHAR) NOT NULL ENABLE, 
	"CODIGO_ANTERIOR" VARCHAR2(80 CHAR), 
	 CONSTRAINT "CK_ANUNCIOS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_ANUNCIOS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_ANUNCIOS_1" CHECK (VIGENTE_HASTA >= VIGENTE_DESDE) ENABLE, 
	 CONSTRAINT "CK_ANUNCIOS_2" CHECK (PARA_TODOS IN (0,1)) ENABLE, 
	 CONSTRAINT "PK_ANUNCIOS" PRIMARY KEY ("ID_ANUNCIO")
  USING INDEX  ENABLE, 
	 CHECK (VERSION > 0) ENABLE, 
	 CONSTRAINT "UQ_ANUNCIOS_CODIGO" UNIQUE ("CODIGO")
  USING INDEX  ENABLE
   );

-- TABLE: BANCOS
CREATE TABLE "BANCOS" 
