-- TABLE: EVENTOS
CREATE TABLE "EVENTOS" 
   (	"ID_EVENTO" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"TITULO" VARCHAR2(200 CHAR) NOT NULL ENABLE, 
	"DESCRIPCION" CLOB, 
	"FECHA_INICIO" DATE NOT NULL ENABLE, 
	"FECHA_FIN" DATE NOT NULL ENABLE, 
	"LUGAR" VARCHAR2(250 CHAR) NOT NULL ENABLE, 
	"PARA_TODOS" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"VERSION" NUMBER(10,0) DEFAULT 1 NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(80 CHAR) NOT NULL ENABLE, 
	"CODIGO_ANTERIOR" VARCHAR2(80 CHAR), 
	 CONSTRAINT "CK_EVENTOS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_EVENTOS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_EVENTOS_1" CHECK (FECHA_FIN >= FECHA_INICIO) ENABLE, 
	 CONSTRAINT "CK_EVENTOS_2" CHECK (PARA_TODOS IN (0,1)) ENABLE, 
	 CONSTRAINT "PK_EVENTOS" PRIMARY KEY ("ID_EVENTO")
  USING INDEX  ENABLE, 
	 CHECK (VERSION > 0) ENABLE, 
	 CONSTRAINT "UQ_EVENTOS_CODIGO" UNIQUE ("CODIGO")
  USING INDEX  ENABLE
   );

-- TABLE: FERIADOS
CREATE TABLE "FERIADOS" 
   (	"ID_FERIADO" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(60 CHAR) NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(120 CHAR) NOT NULL ENABLE, 
	"FECHA" DATE NOT NULL ENABLE, 
	"FECHA_CONMEMORACION" DATE NOT NULL ENABLE, 
	"AMBITO" VARCHAR2(10 CHAR) DEFAULT 'NACIONAL' NOT NULL ENABLE, 
	"LOCALIDAD" VARCHAR2(120 CHAR) DEFAULT '*' NOT NULL ENABLE, 
	"MINUTO_INICIO" NUMBER(4,0) DEFAULT 0 NOT NULL ENABLE, 
	"MINUTO_FIN" NUMBER(4,0) DEFAULT 1440 NOT NULL ENABLE, 
	"FUNDAMENTO" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CODIGO_ANTERIOR" VARCHAR2(80 CHAR), 
	 CONSTRAINT "CK_FERIADOS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_FERIADOS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_FERIADOS_1" CHECK (AMBITO IN ('NACIONAL','LOCAL')) ENABLE, 
	 CONSTRAINT "CK_FERIADOS_2" CHECK ((AMBITO = 'NACIONAL' AND LOCALIDAD = '*') OR (AMBITO = 'LOCAL' AND LOCALIDAD <> '*')) ENABLE, 
	 CONSTRAINT "CK_FERIADOS_3" CHECK (FECHA = TRUNC(FECHA)) ENABLE, 
	 CONSTRAINT "CK_FERIADOS_4" CHECK (MINUTO_INICIO >= 0 AND MINUTO_FIN <= 1440 AND MINUTO_FIN > MINUTO_INICIO) ENABLE, 
	 CONSTRAINT "PK_FERIADOS" PRIMARY KEY ("ID_FERIADO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_FERIADOS_1" UNIQUE ("CODIGO", "FECHA_CONMEMORACION", "LOCALIDAD")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_FERIADOS_2" UNIQUE ("FECHA", "LOCALIDAD", "MINUTO_INICIO")
  USING INDEX  ENABLE
   );

