-- TABLE: PERIODOS_NOMINA
CREATE TABLE "PERIODOS_NOMINA" 
   (	"ID_PERIODO_NOMINA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"FECHA_INICIO" DATE NOT NULL ENABLE, 
	"FECHA_FIN" DATE NOT NULL ENABLE, 
	"QUINCENA" NUMBER(1,0) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(12 CHAR) DEFAULT 'ABIERTO' NOT NULL ENABLE, 
	"VERSION_CALCULO" NUMBER(5,0) DEFAULT 0 NOT NULL ENABLE, 
	"CALCULADO_EN" DATE, 
	"REVISADO_EN" DATE, 
	"APROBADO_EN" DATE, 
	"CERRADO_EN" DATE, 
	"APROBADO_POR" NUMBER, 
	"CERRADO_POR" NUMBER, 
	"MOTIVO_REAPERTURA" VARCHAR2(500 CHAR), 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"HASH_FUENTES" VARCHAR2(64 CHAR), 
	"ALERTAS" CLOB DEFAULT '[]' NOT NULL ENABLE, 
	"MOTOR" VARCHAR2(2 CHAR) DEFAULT 'V0' NOT NULL ENABLE, 
	 CONSTRAINT "CK_PERIODOS_NOMINA_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_PERIODOS_NOMINA_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_PERIODOS_NOMINA_1" CHECK (QUINCENA IN (1,2)) ENABLE, 
	 CONSTRAINT "CK_PERIODOS_NOMINA_2" CHECK (FECHA_INICIO = TRUNC(FECHA_INICIO) AND FECHA_FIN = TRUNC(FECHA_FIN)) ENABLE, 
	 CONSTRAINT "CK_PERIODOS_NOMINA_3" CHECK ((QUINCENA = 1 AND EXTRACT(DAY FROM FECHA_INICIO) = 1 AND FECHA_FIN = FECHA_INICIO + 14) OR (QUINCENA = 2 AND EXTRACT(DAY FROM FECHA_INICIO) = 16 AND FECHA_FIN = LAST_DAY(FECHA_INICIO))) ENABLE, 
	 CONSTRAINT "CK_PERIODOS_NOMINA_4" CHECK (ESTADO IN ('ABIERTO','CALCULADO','REVISADO','APROBADO','CERRADO')) ENABLE, 
	 CONSTRAINT "CK_PERIODOS_NOMINA_5" CHECK (VERSION_CALCULO >= 0) ENABLE, 
	 CONSTRAINT "CK_PERIODOS_NOMINA_6" CHECK (ESTADO <> 'CERRADO' OR (CERRADO_EN IS NOT NULL AND CERRADO_POR IS NOT NULL)) ENABLE, 
	 CONSTRAINT "CK_PERIODOS_NOMINA_7" CHECK (ESTADO NOT IN ('APROBADO','CERRADO') OR (APROBADO_EN IS NOT NULL AND APROBADO_POR IS NOT NULL)) ENABLE, 
	 CONSTRAINT "PK_PERIODOS_NOMINA" PRIMARY KEY ("ID_PERIODO_NOMINA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_PERIODOS_NOMINA_1" UNIQUE ("FECHA_INICIO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_PERIODO_ALERTAS_JSON" CHECK (ALERTAS IS JSON) ENABLE, 
	 CONSTRAINT "CK_PERIODO_MOTOR" CHECK (MOTOR IN ('V0','V1')) ENABLE
   );

