	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"SALARIO_MINIMO" NUMBER(12,2), 
	"SALARIO_MAXIMO" NUMBER(12,2), 
	"CODIGO_ANTERIOR" VARCHAR2(80 CHAR), 
	 CONSTRAINT "CK_PUESTOS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_PUESTOS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
