  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_PUESTOS_1" UNIQUE ("CODIGO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_PUESTOS_2" UNIQUE ("ID_PUESTO", "ID_DEPARTAMENTO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_PUESTOS_RANGO" CHECK (
  (SALARIO_MINIMO IS NULL AND SALARIO_MAXIMO IS NULL) OR
  (SALARIO_MINIMO IS NOT NULL AND SALARIO_MAXIMO IS NOT NULL AND SALARIO_MINIMO >= 0 AND SALARIO_MAXIMO >= SALARIO_MINIMO)
) ENABLE
   );

