	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_HBD_DIA" CHECK (DIA_SEMANA BETWEEN 1 AND 7) ENABLE, 
	 CONSTRAINT "CK_HBD_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_HBD_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "PK_HORARIO_BLOQUE_DIAS" PRIMARY KEY ("ID_HORARIO_BLOQUE_DIA")
  USING INDEX  ENABLE, 
