   );

-- TABLE: EMPLEADOS
CREATE TABLE "EMPLEADOS" 
   (	"ID_EMPLEADO" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_USUARIO" NUMBER, 
	"CODIGO" VARCHAR2(40 CHAR) NOT NULL ENABLE, 
	"NOMBRES" VARCHAR2(100 CHAR) NOT NULL ENABLE, 
	"APELLIDOS" VARCHAR2(100 CHAR) NOT NULL ENABLE, 
	"DPI" VARCHAR2(13 CHAR) NOT NULL ENABLE, 
	"NIT" VARCHAR2(20 CHAR) NOT NULL ENABLE, 
	"AFILIACION_IGSS" VARCHAR2(20 CHAR), 
	"FECHA_NACIMIENTO" DATE NOT NULL ENABLE, 
	"SEXO" VARCHAR2(1 CHAR), 
	"ESTADO_CIVIL" VARCHAR2(20 CHAR) NOT NULL ENABLE, 
	"DIRECCION" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"TELEFONO" VARCHAR2(8 CHAR) NOT NULL ENABLE, 
	"CORREO" VARCHAR2(254 CHAR) NOT NULL ENABLE, 
	"ID_BANCO" NUMBER, 
	"CUENTA_BANCARIA" VARCHAR2(34 CHAR), 
	"TIPO_CUENTA" VARCHAR2(15 CHAR), 
	"ID_PUESTO" NUMBER NOT NULL ENABLE, 
	"ID_DEPARTAMENTO" NUMBER NOT NULL ENABLE, 
	"ID_JEFATURA" NUMBER, 
	"ID_TIPO_CONTRATO" NUMBER NOT NULL ENABLE, 
	"ID_CENTRO_TRABAJO" NUMBER NOT NULL ENABLE, 
	"FECHA_INGRESO" DATE NOT NULL ENABLE, 
	"FECHA_FIN_CONTRATO" DATE, 
	"FECHA_EGRESO" DATE, 
	"MOTIVO_EGRESO" VARCHAR2(500 CHAR), 
	"ESTADO" VARCHAR2(15 CHAR) DEFAULT 'ACTIVO' NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CODIGO_ANTERIOR" VARCHAR2(80 CHAR), 
	"DIRECCION_ANTERIOR" VARCHAR2(500 CHAR), 
	"SEXO_ANTERIOR" VARCHAR2(1 CHAR), 
	"ID_DEPARTAMENTO_GT" NUMBER, 
	"ID_MUNICIPIO_GT" NUMBER, 
	"ZONA" NUMBER(2,0), 
	"NUMERO_CASA" VARCHAR2(20 CHAR), 
	 CONSTRAINT "CK_EMPLEADOS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_1" CHECK (REGEXP_LIKE(DPI, '^[0-9]{13}$')) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_2" CHECK (REGEXP_LIKE(NIT, '^[0-9]+-[0-9K]$')) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_3" CHECK (REGEXP_LIKE(AFILIACION_IGSS, '^[0-9]+$')) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_5" CHECK (ESTADO_CIVIL IN ('SOLTERO','CASADO','UNIDO','DIVORCIADO','VIUDO')) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_6" CHECK (REGEXP_LIKE(TELEFONO, '^[0-9]{8}$')) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_7" CHECK (CORREO = LOWER(TRIM(CORREO)) AND INSTR(CORREO, '@') > 1) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_8" CHECK (TIPO_CUENTA IN ('AHORRO','MONETARIA')) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_9" CHECK ((ID_BANCO IS NULL AND CUENTA_BANCARIA IS NULL AND TIPO_CUENTA IS NULL) OR (ID_BANCO IS NOT NULL AND CUENTA_BANCARIA IS NOT NULL AND TIPO_CUENTA IS NOT NULL)) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_10" CHECK (ESTADO IN ('ACTIVO','SUSPENDIDO','EGRESADO')) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_11" CHECK (FECHA_NACIMIENTO < FECHA_INGRESO) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_12" CHECK (FECHA_EGRESO IS NULL OR FECHA_EGRESO >= FECHA_INGRESO) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_13" CHECK (FECHA_FIN_CONTRATO IS NULL OR FECHA_FIN_CONTRATO >= FECHA_INGRESO) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_14" CHECK ((ESTADO = 'EGRESADO' AND FECHA_EGRESO IS NOT NULL AND MOTIVO_EGRESO IS NOT NULL) OR (ESTADO <> 'EGRESADO' AND FECHA_EGRESO IS NULL)) ENABLE, 
	 CONSTRAINT "PK_EMPLEADOS" PRIMARY KEY ("ID_EMPLEADO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_EMPLEADOS_1" UNIQUE ("CODIGO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_EMPLEADOS_2" UNIQUE ("DPI")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_EMPLEADOS_3" UNIQUE ("NIT")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_EMPLEADOS_4" UNIQUE ("AFILIACION_IGSS")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_EMPLEADOS_5" UNIQUE ("CORREO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_EMPLEADOS_6" UNIQUE ("ID_USUARIO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_GT_PAR" CHECK ((ID_DEPARTAMENTO_GT IS NULL AND ID_MUNICIPIO_GT IS NULL) OR (ID_DEPARTAMENTO_GT IS NOT NULL AND ID_MUNICIPIO_GT IS NOT NULL)) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_ZONA" CHECK (ZONA BETWEEN 1 AND 25 AND ZONA=TRUNC(ZONA)) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_CASA" CHECK (REGEXP_LIKE(NUMERO_CASA,'^[A-Za-z0-9]+(-[A-Za-z0-9]+)*$')) ENABLE, 
	 CONSTRAINT "CK_EMPLEADOS_4" CHECK (SEXO IN ('F','M')) ENABLE
   );

-- TABLE: AUSENCIAS
CREATE TABLE "AUSENCIAS" 
   (	"ID_AUSENCIA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"ID_TIPO_AUSENCIA" NUMBER NOT NULL ENABLE, 
	"FECHA_INICIO" DATE NOT NULL ENABLE, 
	"FECHA_FIN" DATE NOT NULL ENABLE, 
	"DIAS" NUMBER(7,2) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(12 CHAR) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"MOTIVO" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"RUTA_SOPORTE" VARCHAR2(500 CHAR), 
	"APROBADO_POR" NUMBER, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"SOPORTE" BLOB, 
	"SOPORTE_NOMBRE" VARCHAR2(150 CHAR), 
	"SOPORTE_TIPO" VARCHAR2(30 CHAR), 
	 CONSTRAINT "CK_AUSENCIAS_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_AUSENCIAS_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_AUSENCIAS_1" CHECK (FECHA_FIN >= FECHA_INICIO) ENABLE, 
	 CONSTRAINT "CK_AUSENCIAS_2" CHECK (DIAS > 0) ENABLE, 
	 CONSTRAINT "CK_AUSENCIAS_3" CHECK (ESTADO IN ('PENDIENTE','APROBADA','RECHAZADA')) ENABLE, 
	 CONSTRAINT "CK_AUSENCIAS_4" CHECK (ESTADO <> 'APROBADA' OR APROBADO_POR IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_AUSENCIAS" PRIMARY KEY ("ID_AUSENCIA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_AUSENCIAS_1" UNIQUE ("ID_AUSENCIA", "ID_EMPLEADO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_AUSENCIA_SOPORTE" CHECK ((SOPORTE_NOMBRE IS NULL AND SOPORTE_TIPO IS NULL) OR (SOPORTE_NOMBRE IS NOT NULL AND SOPORTE_TIPO IN ('application/pdf','image/png','image/jpeg'))) ENABLE
   );

