-- TABLE: ISR_APERTURAS
CREATE TABLE "ISR_APERTURAS" 
   (	"ID_ISR_APERTURA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"ANIO" NUMBER(4,0) NOT NULL ENABLE, 
	"FECHA_CORTE" DATE NOT NULL ENABLE, 
	"RENTA" NUMBER(12,2) NOT NULL ENABLE, 
	"IGSS" NUMBER(12,2) NOT NULL ENABLE, 
	"ISR" NUMBER(12,2) NOT NULL ENABLE, 
	"MOTIVO" VARCHAR2(500 CHAR) NOT NULL ENABLE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	 CONSTRAINT "CK_ISR_APERTURA_VAL" CHECK (RENTA>=0 AND IGSS>=0 AND ISR>=0) ENABLE, 
	 CONSTRAINT "CK_ISR_APERTURA_CORTE" CHECK (ANIO BETWEEN 2000 AND 9999 AND EXTRACT(YEAR FROM FECHA_CORTE)=ANIO AND FECHA_CORTE=TRUNC(FECHA_CORTE) AND (EXTRACT(DAY FROM FECHA_CORTE)=15 OR FECHA_CORTE=LAST_DAY(FECHA_CORTE))) ENABLE, 
	 CONSTRAINT "CK_ISR_APERTURA_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_ISR_APERTURA_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION>=FECHA_CREACION) ENABLE, 
	 CONSTRAINT "PK_ISR_APERTURAS" PRIMARY KEY ("ID_ISR_APERTURA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_ISR_APERTURA_EMP" UNIQUE ("ID_EMPLEADO", "ANIO")
  USING INDEX  ENABLE
   );

