	"OBSERVACIONES" VARCHAR2(1000 CHAR), 
	"RESUELTO_POR" NUMBER, 
	"RESUELTO_EN" DATE, 
	"MOTIVO_RECHAZO" VARCHAR2(500 CHAR), 
	"ENTREGADA_EN" DATE, 
	"CREADO_POR" NUMBER, 
	"FECHA_CREACION" DATE DEFAULT CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE) NOT NULL ENABLE, 
	"MODIFICADO_POR" NUMBER, 
	"FECHA_MODIFICACION" DATE, 
	"ACTIVO" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(80 CHAR) NOT NULL ENABLE, 
	"CODIGO_ANTERIOR" VARCHAR2(80 CHAR), 
	"VEHICULO" VARCHAR2(5 CHAR), 
	"PLACA" VARCHAR2(12 CHAR), 
	 CONSTRAINT "CK_SOLICITUDES_ACT" CHECK (ACTIVO IN (0,1)) ENABLE, 
	 CONSTRAINT "CK_SOLICITUDES_MOD" CHECK (FECHA_MODIFICACION IS NULL OR FECHA_MODIFICACION >= FECHA_CREACION) ENABLE, 
	 CONSTRAINT "CK_SOLICITUDES_2" CHECK (DATOS_SOLICITADOS IS JSON) ENABLE, 
	 CONSTRAINT "CK_SOLICITUDES_3" CHECK (ESTADO <> 'RECHAZADA' OR MOTIVO_RECHAZO IS NOT NULL) ENABLE, 
	 CONSTRAINT "CK_SOLICITUDES_4" CHECK (ESTADO = 'EN_PROCESO' OR (RESUELTO_POR IS NOT NULL AND RESUELTO_EN IS NOT NULL)) ENABLE, 
	 CONSTRAINT "CK_SOLICITUDES_5" CHECK (ESTADO <> 'ENTREGADA' OR ENTREGADA_EN IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_SOLICITUDES" PRIMARY KEY ("ID_SOLICITUD")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_SOLICITUDES_1" UNIQUE ("ID_SOLICITUD", "ID_EMPLEADO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_SOLICITUDES_CODIGO" UNIQUE ("CODIGO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_SOLICITUDES_1" CHECK (ESTADO IN ('EN_PROCESO','APROBADA','RECHAZADA','ENTREGADA','CANCELADA')) ENABLE, 
	 CONSTRAINT "CK_SOL_VEHICULO" CHECK (VEHICULO IN ('CARRO','MOTO')) ENABLE
