-- TABLE: PAGOS_NOMINA
CREATE TABLE "PAGOS_NOMINA" 
   (	"ID_PAGO_NOMINA" NUMBER GENERATED ALWAYS AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
