FOR EACH ROW
BEGIN
  :NEW.FECHA_MODIFICACION := CAST(SYSTIMESTAMP AT TIME ZONE 'America/Guatemala' AS DATE);
END;
/

ALTER TRIGGER "TR_TIPOS_DEDUCCION_ISR_MOD" ENABLE;

-- TRIGGER: TR_TIPOS_DESCUENTO_CODIGO
CREATE OR REPLACE EDITIONABLE TRIGGER "TR_TIPOS_DESCUENTO_CODIGO" 
BEFORE INSERT OR UPDATE OF CODIGO,CODIGO_ANTERIOR ON TIPOS_DESCUENTO FOR EACH ROW
BEGIN
  IF INSERTING THEN
    :NEW.CODIGO_ANTERIOR:=:NEW.CODIGO;
    :NEW.CODIGO:=N2_CODIGOS.ASIGNAR('tipos-descuento',:NEW.NOMBRE,NULL,:NEW.FECHA_CREACION,:NEW.CODIGO);
  ELSIF :NEW.CODIGO<>:OLD.CODIGO OR :NEW.CODIGO IS NULL OR NVL(:NEW.CODIGO_ANTERIOR,CHR(0))<>NVL(:OLD.CODIGO_ANTERIOR,CHR(0)) THEN
    RAISE_APPLICATION_ERROR(-20042,'El código asignado y su referencia anterior son inmutables.');
  END IF;
END;
/

ALTER TRIGGER "TR_TIPOS_DESCUENTO_CODIGO" ENABLE;

