  '1905' "CODIGO_INE",
  'Teculután' "NOMBRE",
  1 "ACTIVO",
  (SELECT ID_DEPARTAMENTO_GT FROM DEPARTAMENTOS_GT WHERE CODIGO_INE='19') "ID_DEPARTAMENTO_GT"
FROM DUAL) O
ON (D."CODIGO_INE"=O."CODIGO_INE")
WHEN NOT MATCHED THEN INSERT ("CODIGO_INE","NOMBRE","ACTIVO","ID_DEPARTAMENTO_GT")
VALUES (O."CODIGO_INE",O."NOMBRE",O."ACTIVO",O."ID_DEPARTAMENTO_GT");

