-- ==================== 05_verificar.sql ====================
-- Verificación de instalación nueva, antes de empezar a operar (conteos exactos).
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF SQLBLANKLINES ON SERVEROUTPUT ON
DECLARE N NUMBER;
BEGIN
  SELECT COUNT(*) INTO N FROM USER_OBJECTS WHERE STATUS<>'VALID';
  IF N<>0 THEN RAISE_APPLICATION_ERROR(-20091,'Objetos inválidos: se esperaba 0'); END IF;
  SELECT COUNT(*) INTO N FROM USER_CONSTRAINTS WHERE STATUS<>'ENABLED' OR VALIDATED<>'VALIDATED';
  IF N<>0 THEN RAISE_APPLICATION_ERROR(-20091,'Constraints deshabilitadas o no validadas: se esperaba 0'); END IF;
  SELECT COUNT(*) INTO N FROM USER_TAB_IDENTITY_COLS;
  IF N<>73 THEN RAISE_APPLICATION_ERROR(-20091,'Identities: se esperaba 73'); END IF;
  SELECT COUNT(*) INTO N FROM VERSION_ESQUEMA WHERE ESTADO='APLICADA';
  IF N<>31 THEN RAISE_APPLICATION_ERROR(-20091,'Migraciones: se esperaba 31'); END IF;
  SELECT COUNT(*) INTO N FROM USUARIOS U JOIN ROLES R ON R.ID_ROL=U.ID_ROL WHERE U.USUARIO='admin.inicial' AND R.CODIGO='ADMIN' AND U.CAMBIO_OBLIGATORIO=1;
  IF N<>1 THEN RAISE_APPLICATION_ERROR(-20091,'ADMIN inicial con cambio obligatorio: se esperaba 1'); END IF;
  SELECT COUNT(*) INTO N FROM USUARIOS;
  IF N<>1 THEN RAISE_APPLICATION_ERROR(-20091,'Solo el usuario sintético: se esperaba 1'); END IF;
  SELECT COUNT(*) INTO N FROM REGISTRO_CODIGOS WHERE ENTIDAD NOT IN ('tipos-contrato','tipos-descuento','tipos-ausencia','tipos-solicitud','parametros-legales','feriados');
  IF N<>0 THEN RAISE_APPLICATION_ERROR(-20091,'Reservas privadas excluidas: se esperaba 0'); END IF;
  SELECT COUNT(*) INTO N FROM USER_OBJECTS WHERE OBJECT_TYPE='INDEX';
  IF N<>763 THEN RAISE_APPLICATION_ERROR(-20091,'Objetos INDEX: se esperaba 763'); END IF;
  SELECT COUNT(*) INTO N FROM USER_OBJECTS WHERE OBJECT_TYPE='LOB';
  IF N<>22 THEN RAISE_APPLICATION_ERROR(-20091,'Objetos LOB: se esperaba 22'); END IF;
  SELECT COUNT(*) INTO N FROM USER_OBJECTS WHERE OBJECT_TYPE='PACKAGE';
  IF N<>1 THEN RAISE_APPLICATION_ERROR(-20091,'Objetos PACKAGE: se esperaba 1'); END IF;
  SELECT COUNT(*) INTO N FROM USER_OBJECTS WHERE OBJECT_TYPE='PACKAGE BODY';
  IF N<>1 THEN RAISE_APPLICATION_ERROR(-20091,'Objetos PACKAGE BODY: se esperaba 1'); END IF;
  SELECT COUNT(*) INTO N FROM USER_OBJECTS WHERE OBJECT_TYPE='SEQUENCE';
  IF N<>73 THEN RAISE_APPLICATION_ERROR(-20091,'Objetos SEQUENCE: se esperaba 73'); END IF;
  SELECT COUNT(*) INTO N FROM USER_OBJECTS WHERE OBJECT_TYPE='TABLE';
  IF N<>73 THEN RAISE_APPLICATION_ERROR(-20091,'Objetos TABLE: se esperaba 73'); END IF;
  SELECT COUNT(*) INTO N FROM USER_OBJECTS WHERE OBJECT_TYPE='TRIGGER';
  IF N<>82 THEN RAISE_APPLICATION_ERROR(-20091,'Objetos TRIGGER: se esperaba 82'); END IF;
  SELECT COUNT(*) INTO N FROM "ROLES";
  IF N<>3 THEN RAISE_APPLICATION_ERROR(-20091,'Catálogo ROLES: se esperaba 3'); END IF;
  SELECT COUNT(*) INTO N FROM "CONFIG_CODIGOS";
  IF N<>18 THEN RAISE_APPLICATION_ERROR(-20091,'Catálogo CONFIG_CODIGOS: se esperaba 18'); END IF;
  SELECT COUNT(*) INTO N FROM "DEPARTAMENTOS_GT";
  IF N<>22 THEN RAISE_APPLICATION_ERROR(-20091,'Catálogo DEPARTAMENTOS_GT: se esperaba 22'); END IF;
  SELECT COUNT(*) INTO N FROM "MUNICIPIOS_GT";
  IF N<>340 THEN RAISE_APPLICATION_ERROR(-20091,'Catálogo MUNICIPIOS_GT: se esperaba 340'); END IF;
