  IF N<>3 THEN RAISE_APPLICATION_ERROR(-20091,'Catálogo TIPOS_CONTRATO: se esperaba 3'); END IF;
  SELECT COUNT(*) INTO N FROM "TIPOS_DESCUENTO";
  IF N<>6 THEN RAISE_APPLICATION_ERROR(-20091,'Catálogo TIPOS_DESCUENTO: se esperaba 6'); END IF;
